import { Card } from '@refy-design/web';
import { Section } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof Section>,
    'layout' | 'reverse' | 'children' | 'aside'
  > = {
    layout: 'split',
    reverse: false,
    children: (
      <div>
        <h2>Build new components from the ones that exist.</h2>
        <p>Combine atoms into a new molecule.</p>
      </div>
    ),
    aside: <Card>Proof</Card>,
  };
  return <Section {...args} />;
}

